export const managementViews={
 'eco-woodland-benefits':[['renewal','Harvest & renewal'],['goods','Four woodland uses'],['habitat','Habitat features'],['visitors','Visitor pressure']],
 'eco-woodland-climate':[['stress','Water stress'],['timing','Seasonal mismatch'],['categories','Three kinds of change'],['resilience','Compare responses']],
 'eco-woodland-clearance':[['urban','Urban conversion'],['harvest','Harvest or conversion?'],['farming','Field expansion'],['compare','Cover & habitat']],
 'eco-epping-management':[['trees','Veteran-tree care'],['locator','Locate Epping'],['grazing','Conservation grazing'],['access','Public access']],
 'eco-population-projections':[['projection','UN selected points'],['interval','2100 uncertainty'],['efficient','Lower-use example'],['intensive','Higher-use example']]
};
export const managementRequirements=Object.fromEntries(Object.entries(managementViews).map(([k,v])=>[k,v.map(x=>x[0])]));
export const managementAnimated=(k,v)=>({'eco-woodland-benefits':['renewal','visitors'],'eco-woodland-climate':['stress','timing'],'eco-woodland-clearance':['urban','harvest','farming'],'eco-epping-management':['trees','grazing']}[k]||[]).includes(v);
export const populationData={release:'UN World Population Prospects2024',unit:'billion people',points:[{year:2024,value:8.2,type:'estimate'},{year:2030,value:8.5,type:'projection'},{year:2085,value:10.3,type:'approximate mid2080s peak;display year only'},{year:2100,value:10.2,type:'medium projection'}],interval:{year:2100,level:95,lower:9,upper:11.4},source:'https://www.un.org/esa/foresight/chapter-three.html',peakSource:'https://india.un.org/en/274068-un-projects-world-population-peak-within-century',intervalSource:'https://www.un.org/development/desa/pd/sites/www.un.org.development.desa.pd/files/wpp2024_summary_of_results_final_web.pdf'};
export const resourceDemand=(population,rate)=>population*rate;
export const woodStock=(start,growth,harvest)=>start+growth-harvest;
const tx=(x,y,s,z=13)=>`<text x="${x}" y="${y}" font-size="${z}">${s}</text>`;
const path=(d,c='#bad0d8',w=3)=>`<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round"/>`;
const dot=(x,y,r=6,c='#efb59f')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}"/>`;
const box=(x,y,w,a,b='')=>`<rect x="${x}" y="${y}" width="${w}" height="${b?65:45}" rx="12" fill="#36566a" stroke="#afc6cf"/>`+tx(x+12,y+26,a,12)+(b?tx(x+12,y+48,b,11):'');
const tree=(x,y,h=145,cover=1)=>path(`M${x} ${y}V${y-h+35}M${x} ${y-60}l-25 -35M${x} ${y-85}l28 -30`,'#c8b18f',7)+`<g opacity="${cover}"><ellipse cx="${x}" cy="${y-h+35}" rx="40" ry="35" fill="#a9bd9e"/><ellipse cx="${x-22}" cy="${y-h+62}" rx="29" ry="28" fill="#8fa98f"/><ellipse cx="${x+22}" cy="${y-h+62}" rx="29" ry="28" fill="#8fa98f"/></g>`;
const land=()=>`<path d="M20 280Q220 270 420 285V305H20Z" fill="#8c7c68"/>`;
const svg=(b,c)=>`<svg class="geo-scene" viewBox="0 0 440 350" role="img" aria-label="${c.replaceAll('&','&amp;').replaceAll('"','&quot;')}"><g fill="#eef2f2" font-family="sans-serif">${b}</g></svg>`;
const wrap=(b,c)=>svg(b,c)+`<p class="geo-caption">${c}</p>`;
const popSource=()=>`<p class="geo-caption">UN WPP2024 · rounded global values · <a href="${populationData.source}" target="_blank" rel="noopener">UN points</a> · <a href="${populationData.peakSource}" target="_blank" rel="noopener">peak</a> · <a href="${populationData.intervalSource}" target="_blank" rel="noopener">2100 range</a>. Estimates and conditional projections,not future observations. Peak plotted at~2085 for display only.</p>`;
export function populationEvidence(neutral=true){const y=v=>290-(v-8)*52;let b=tx(20,28,'UN2024 ·2100GLOBAL POPULATION',14)+tx(20,55,'Billion people ·95%prediction interval',12);for(let n=8;n<=12;n++)b+=path(`M60 ${y(n)}H390`,'#8ea6b344',1)+tx(28,y(n)+4,String(n),12);b+=path(`M250 ${y(11.4)}V${y(9)}`,'#efb59f',5)+path(`M232 ${y(11.4)}H268M232 ${y(9)}H268`,'#efb59f',3)+tx(284,y(11.4)+5,'11.4',14)+tx(284,y(9)+5,'9.0',14)+dot(250,y(10.2),6,'#c2dce3')+tx(284,y(10.2)+5,'10.2 medium',12)+tx(225,322,'2100',14);return wrap(b,neutral?'Rounded UNWPP2024global2100interval and medium projection. Vertical scale in billions;read the endpoint labels.':'The2100model-based95%prediction interval is9.0–11.4billion. The medium trajectory10.2is not certain,and this interval is not the high/low-fertility variants. No interval is interpolated for other years.')+popSource();}
function populationGraph(){const y=v=>290-(v-8)*52,x=v=>60+(v-2024)/76*330;let b=tx(20,28,'GLOBAL POPULATION · UNWPP2024',14)+tx(20,54,'Billion people · selected rounded points',12);for(let n=8;n<=12;n++)b+=path(`M60 ${y(n)}H390`,'#8ea6b344',1)+tx(30,y(n)+4,String(n),12);b+=path('M60 70V290H390','#c6d5dc',2)+`<polyline points="${populationData.points.map(p=>`${x(p.year)},${y(p.value)}`).join(' ')}" fill="none" stroke="#efb59f" stroke-width="3"/>`;for(let p of populationData.points)b+=dot(x(p.year),y(p.value),5)+tx(x(p.year)-12,y(p.value)-14,String(p.value),12);b+=tx(45,315,'2024',11)+tx(x(2060)-14,315,'2060',11)+tx(x(2100)-14,315,'2100',11)+tx(20,337,'Mid2080s peak placed~2085,not an exact date',11);return wrap(b,'Selected published points joined by straight segments,not an annual UNseries or an observed future.2024is an estimate;later points are conditional projections. The late-century small decline is one trajectory,not guaranteed.')+popSource()+`<details class="geo-chart-values"><summary>Read plotted values</summary><table class="geo-data"><caption>UNWPP2024 · global · billion people</caption><thead><tr><th scope="col">Date</th><th scope="col">Value</th><th scope="col">Type</th></tr></thead><tbody>${populationData.points.map(p=>`<tr><th scope="row">${p.year===2085?'Mid2080s (~2085 display)':p.year}</th><td>${p.value}</td><td>${p.type}</td></tr>`).join('')}</tbody></table></details>`;}
export function managementScene(k,v,t=0){if(!managementViews[k])return '';v=managementRequirements[k].includes(v)?v:managementRequirements[k][0];t=managementAnimated(k,v)?Math.max(0,Math.min(1,Number(t)||0)):0;let b='',c='';
if(k==='eco-population-projections'){
 if(v==='projection')return populationGraph();if(v==='interval')return populationEvidence(false);
 const rate=v==='efficient'?10:20,demand=resourceDemand(10.2,rate);b=tx(20,28,'RESOURCE DEMAND · INVENTED COMPARISON',13)+tx(20,60,`Population input:10.2billion · use rate:${rate}`,12)+path('M55 280H410','#c2d4dc',2)+`<rect x="55" y="120" width="${demand*1.5}" height="55" rx="8" fill="#b7caca"/>`+path('M235 95V280','#efb59f',3)+tx(245,105,'Supply120units',12)+tx(65,153,`Demand:${demand}units`,14)+tx(50,305,'0',11)+tx(218,305,'120',11)+tx(370,305,'220',11)+tx(20,335,'Toy resource units · not Earth carrying capacity',11);c=`Same population,${rate}toy resource units per billion gives${demand}demand units. The120unit supply is invented. Supply,consumption,yields,waste,access and ecosystems vary;this is not a UNresource forecast or an exhaustion date.`;
}
if(k==='eco-woodland-benefits'){
 if(v==='renewal'){const stock=100+12*t-9*t;b=tx(20,28,'HARVEST AND GROWTH · INVENTED STOCK',13)+land()+tree(95,280,140+35*t)+tree(310,280,170)+box(165,75,240,'Start100 · growth12','Harvest9 → end103')+dot(310-100*t,200+60*t)+tx(20,330,`Stock:${stock.toFixed(1)} units · habitat assessed separately`,12);c='Toy timber stock adds12growth units and removes9by harvest,finishing103. The loop resets a worked example,not woodland history. Regeneration and stock balance do not alone prove biodiversity protection or instant carbon neutrality.';}
 else if(v==='goods'){b=tx(20,28,'GOODS AND SERVICES',15)+box(25,75,180,'Timber','Material product')+box(235,75,180,'Fuel','Energy product')+box(25,205,180,'Conservation','Habitat / species care')+box(235,205,180,'Recreation','Experience / wellbeing');c='Timber and fuel are harvested products. Conservation and recreation are woodland services and objectives. Their benefits can coexist with trade-offs;all uses do not belong at the same intensity in every habitat.';}
 else if(v==='habitat'){b=tx(20,28,'HABITAT FEATURES HAVE DIFFERENT ROLES',13)+land()+tree(95,280,170)+tree(335,280,130)+path('M155 267l90 10','#c0a383',14)+dot(155,267,8)+tx(25,70,'Old trees',13)+tx(165,245,'Dead wood',13)+tx(275,90,'Varied ages',13)+tx(20,330,'Dead material can support living communities',12);c='Old trees,dead wood and varied structure support different organisms and processes. This static comparison is not a complete habitat inventory or proof a particular management action is suitable everywhere.';}
 else{b=tx(20,28,'RECREATION BENEFITS AND PRESSURES',14)+land()+tree(90,280,160)+tree(350,280,190)+path('M30 300Q220 135 410 300','#c6b18e',7)+dot(35+365*t,300-80*Math.sin(Math.PI*t),8)+tx(20,70,'Walking / local income',13)+tx(20,330,'Trampling / disturbance need management',12);c='Visitor movement illustrates public enjoyment alongside possible pressure on soil and wildlife. Routes,information and monitoring can reduce harm. Dot number,route and speed are symbolic,not visitor capacity or measured damage.';}
}
if(k==='eco-woodland-climate'){
 if(v==='stress'){b=tx(20,28,'LIMITED WATER → STRESS → CANOPY CHANGE',13)+land()+tree(100,280,180,1-.75*t)+tree(330,280,150,1-.4*t)+`<rect x="185" y="${270-90*(1-t)}" width="45" height="${90*(1-t)}" fill="#a3c7d6"/>`+tx(170,305,'Soil water',12)+tx(20,330,'Illustrative sequence,not calibrated mortality',12);c='Dry conditions and increased evaporative demand can reduce available water,restrict growth and affect canopy structure. Response varies with site and species;this loop is not a climate-attribution study or a forecast of tree deaths.';}
 else if(v==='timing'){const x=70+200*t;b=tx(20,28,'TIMING OF CONNECTED SPECIES',14)+path('M50 270H410','#c2d4dc',2)+tx(45,300,'Earlier in spring',12)+tx(290,300,'Later',12)+`<path d="M60 250Q${x} 80 ${x+50} 250" fill="none" stroke="#b9d1c2" stroke-width="4"/>`+path('M315 90V265','#efb59f',3)+tx(20,65,'Insect food peak shifts',13)+tx(255,80,'Chick demand',12)+tx(20,330,'Relative timing matters · not measured dates',12);c='A food peak and chick demand can shift differently. Their overlap affects food availability. This conceptual comparison does not assign real dates or show that every species has the same response to warming.';}
 else if(v==='categories'){b=tx(20,28,'STRUCTURE · FUNCTION · BIODIVERSITY',13)+box(35,65,370,'Structure','Canopy gaps / tree arrangement')+box(35,155,370,'Function','Growth,water and nutrient transfers')+box(35,245,370,'Biodiversity','Species composition / food-web effects');c='The categories distinguish physical arrangement,processes and biological variety. One disturbance can affect all three. Classification is not a numerical impact estimate.';}
 else{b=tx(20,28,'COMPARE RESILIENCE APPROACHES',14)+box(25,80,390,'Site and species suitability','Water limits / soil / conservation goals')+box(25,190,390,'Connections and varied structure','Monitoring and adaptation over time')+tx(20,325,'Longer growth seasons do not remove all constraints',12);c='Longer growing seasons may provide opportunities where water is adequate. Drought,pests and disturbance can increase risks elsewhere. Diverse,suitable management and monitoring may help resilience;no one approach guarantees protection.';}
}
if(k==='eco-woodland-clearance'){
 if(v==='urban'){b=tx(20,28,'URBAN LAND-USE CONVERSION',15)+land();for(let i=0;i<4;i++){let x=65+100*i;b+=t>i/4?`<rect x="${x-28}" y="215" width="56" height="65" rx="4" fill="#9eacb4"/>`+path(`M${x-30} 215l30 -30 30 30`,'#efc1a5',4):tree(x,280,140+i%2*35);}b+=tx(20,330,'Housing / services · choices mediated by planning',12);c='Trees are replaced with a different land use in this urban conversion example. Housing demand,planning and population distribution influence pressure. The drawn buildings and timing are not a real development proposal or area forecast.';}
 else if(v==='harvest'){const cut=t<.45,regrowth=Math.max(0,(t-.45)/.55),height=cut?175*(1-t/.45):150*regrowth;const stem=path(`M100 280V${280-height}`,'#c8b18f',cut?9:4)+(height>25?`<ellipse cx="100" cy="${280-height+15}" rx="${Math.min(38,height*.3)}" ry="${Math.min(32,height*.25)}" fill="#a9bd9e"/>`:'');b=tx(20,28,'HARVEST WITH REGENERATION',15)+land()+stem+(cut?path(`M${115+70*t/.45} 279l45 -10`,'#c8b18f',10):'')+tree(330,280,170)+tx(175,100,cut?'Felling phase':'Regrowth phase',13)+tx(20,330,'Land use remains woodland in this example',12);c='This worked sequence retains woodland land use through felling and regrowth. It simplifies a long process and is not a site-specific forestry recommendation. Permanent conversion must be distinguished from tree-cover loss;new trees do not instantly restore ancient habitat.';}
 else if(v==='farming'){b=tx(20,28,'FIELD EXPANSION AND FRAGMENTATION',13)+land()+tree(65,280,150)+tree(375,280,180)+`<rect x="${150-90*t}" y="210" width="${140+180*t}" height="60" fill="#baaa7a"/>`+path('M220 220v45','#6f7f70',3)+tx(20,70,'Remaining woodland patches',13)+tx(20,330,'Area and habitat connections can change together',12);c='Expanding cultivated land reduces and separates woodland in this symbolic example. Food demand,prices,farming systems,policy and livelihoods influence decisions. No real forest-loss pattern or GIS analysis is inferred from these shapes.';}
 else{b=tx(20,28,'TREE COVER IS NOT THE WHOLE HABITAT',13)+box(25,75,180,'Age / dead wood','Ecological history')+box(235,75,180,'Patch links','Movement routes')+box(75,215,290,'Tree counts / total area','Only some dimensions')+tx(20,330,'A young replacement is not instantly equivalent',12);c='Cover,age,dead wood,soils and connectivity describe different aspects of woodland condition. This comparison does not treat every planted tree as ecologically equivalent to an ancient woodland tree.';}
}
if(k==='eco-epping-management'){
 if(v==='locator'){b=tx(20,28,'EPPING FOREST · SOUTH-EAST ENGLAND',13)+`<path d="M90 70L200 80 265 160 330 240 230 275 130 220 70 135Z" fill="#819b8e" stroke="#c2d2cc"/>`+dot(275,233,7)+path('M283 233L350 205')+tx(290,190,'Epping',14)+tx(25,315,'Essex / Greater London · varied habitat mosaic',12)+tx(25,337,'Schematic locator · not a boundary or scaled map',11);c='Epping Forest extends through Essex and Greater London in south-east England. It includes deciduous woodland,wood-pasture and open or wet habitats. This schematic locator is not a surveyed boundary or evidence of forest-loss distribution.';}
 else if(v==='trees'){const growth=t<.4?1-t/.4:(t-.4)/.6,length=90*growth;const pollard=path('M140 280V175','#c8b18f',11)+path(`M140 175V${175-length}M140 175l${-length*.6} ${-length*.8}M140 175l${length*.6} ${-length*.8}`,'#c8b18f',5)+dot(140,175,7,'#edc6a7')+(length>10?`<ellipse cx="140" cy="${175-length+15}" rx="${10+length*.45}" ry="${8+length*.3}" fill="#a9bd9e"/>`:'');b=tx(20,28,'VETERAN-TREE CARE · POLLARD REGROWTH',13)+land()+pollard+tree(340,280,145)+tx(20,70,t<.4?'Branches cut above ground':'Regrowth over a longer period',13)+tx(20,330,'Specialist,tree-specific work · symbolic timing',12);c='The City’s2024account describes pollarding and veteran-tree work intended to improve longevity and habitat. This schematic shows possible branch regrowth,not instructions for cutting old trees or evidence that every tree tolerates the same treatment.';}
 else if(v==='grazing'){b=tx(20,28,'GRAZING MAINTAINS SOME OPEN HABITATS',13)+land()+tree(75,280,160)+tree(360,280,175)+`<ellipse cx="${120+180*t}" cy="248" rx="26" ry="16" fill="#d5c2aa"/>`+path(`M${105+180*t} 258v20m30-20v20`,'#d5c2aa',4)+tx(20,70,'Varied vegetation height / wood-pasture',12)+tx(20,330,'Monitor browsing,regeneration and animal welfare',12);c='Epping’s conservation cattle grazing helps maintain a mosaic of grassland,heath and wood-pasture. The marker shows one symbolic grazer,not a stocking rate. Excessive browsing can damage regeneration,so location,intensity and ecological impacts need monitoring.';}
 else{b=tx(20,28,'PUBLIC ENJOYMENT WITH CONSERVATION',13)+box(25,75,390,'Routes / information / visitor behaviour','Manage trampling,disturbance and safety')+box(25,195,390,'Monitoring / volunteers / governance','Assess habitat and access outcomes')+tx(20,330,'City of London Corporation · Conservators',12);c='Different approaches serve conservation and public enjoyment. Evaluate access measures and participation with ecological evidence;neither more visitors nor more restrictions is automatically a sustainability measure. This is a policy comparison,not a map of current access rules.';}
}
return wrap(b,c);}
